INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'CREA.G3.CREATI.PUSHING_AND_PULLING', 'creative_activities', 3, 'Tell pushing from pulling in physical activities', ARRAY['CREA.G3.CREATI.PUSHING_AND_PULLING.a']::text[], 'The child says pushing moves something away from the body (a wheelbarrow, a door, a friend''s back in a pushing game) and pulling brings it towards the body (a rope in tug of war, a bucket from a well), sorts everyday and game actions into the two, and says why players keep their own space and push or pull without jerking. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: b) perform pulling and pushing activities for flexibility.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'CREA.G3.CREATI.DRAWING_AND_PAINTING', 'creative_activities', 3, 'Name the colours made by mixing two colours, and the spraying and blowing techniques', ARRAY['CREA.G3.CREATI.DRAWING_AND_PAINTING.a']::text[], 'The child names the secondary colour each pair of primaries makes (red and yellow make orange, blue and yellow make green, red and blue make purple), says that in spraying paint is flicked from an old brush and in blowing a drop of thin paint is blown with a straw so the colours run into each other, and says why brushes and hands are washed after painting. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: b) mix colours using spraying and blowing techniques; d) create a painting for self-expression.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'CREA.G3.CREATI.DRAWING_AND_PAINTING', 'creative_activities', 3, 'Tell regular from irregular shapes in a picture', ARRAY['CREA.G3.CREATI.DRAWING_AND_PAINTING.c']::text[], 'The child names the regular shapes (circle, square, triangle, rectangle) in a picture, says that irregular shapes have no fixed form (a leaf, a cloud, a stone, a puddle), and points out both kinds in a simple drawing such as a house with a tree. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: c) draw a picture using regular and irregular shapes.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_activities', 3, 'Tell long sounds from short sounds in a simple song', ARRAY['CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.a']::text[], 'The child says how long each French rhythm name lasts (ta-te is two short sounds in one beat, taa one beat, taa-aa two beats, taa-aa-aa-aa four beats), picks the longer and the shorter of two sounds in a known song, and matches clapped words to their rhythm names (Ke-nya is ta-te; the held ''sun'' of a song is taa-aa). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: b) create a simple rhythmic pattern using long and short sounds; c) improvise rhythmic accompaniment to simple songs using long and short sounds.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_activities', 3, 'Say what a random repeat pattern is', ARRAY['CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.d']::text[], 'The child says a random repeat pattern repeats the same print (a leaf, a bottle top, a cut potato) many times placed anywhere on the paper, unlike a regular pattern in straight rows, and names found objects that make good prints. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: d) make a random repeat pattern using found objects.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS', 'CREA.G3.CREATI.SKIPPING', 'creative_activities', 3, 'Name the directions and floor patterns of skipping', ARRAY['CREA.G3.CREATI.SKIPPING.a']::text[], 'The child names the directions of skipping (forward, backward, to the right, to the left), tells right from left by their own hands, and names the floor patterns a skipper can make (a straight line, a curve, a circle, a zigzag). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: b) skip in different directions for skill acquisition; c) make patterns while skipping in different ways.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.COLLAGE.COLLAGE', 'CREA.G3.CREATI.COLLAGE', 'creative_activities', 3, 'Say what a collage is and how its materials are prepared', ARRAY['CREA.G3.CREATI.COLLAGE.a', 'CREA.G3.CREATI.COLLAGE.b']::text[], 'The child says a collage is a picture made by pasting pieces of different materials (coloured paper, cloth, seeds, leaves, feathers) onto a surface, says how materials are prepared (collect, clean and dry, cut or tear, sort by colour, make a flour or cassava paste), and tells a collage from a drawing or a painting. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: c) create a collage for self-expression.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.MELODY.MELODY_VARIATION', 'CREA.G3.CREATI.MELODY', 'creative_activities', 3, 'Say how a simple melody has been varied', ARRAY['CREA.G3.CREATI.MELODY.a']::text[], 'The child hears a familiar tune sung again with one change and says what changed: faster or slower (tempo), louder or softer (volume), higher or lower (pitch), a new rhythm or new words. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.MELODY.PERF_DIRECTIONS', 'CREA.G3.CREATI.MELODY', 'creative_activities', 3, 'Follow the performance directions slow, fast, loud and soft', ARRAY['CREA.G3.CREATI.MELODY.c']::text[], 'The child says what each performance direction asks (slow, fast, loud, soft), that loud is not shouting and soft is not whispering out of tune, and follows the teacher''s hand signs (hands wide for loud, close for soft) when told of them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: b) create melodic patterns using improvised percussions; c) apply performance directions in performing simple songs.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.CREATI.WEAVING.PAPER_WEAVE', 'CREA.G3.CREATI.WEAVING', 'creative_activities', 3, 'Say how a plain paper weave is made', ARRAY['CREA.G3.CREATI.WEAVING.a']::text[], 'The child says a plain paper weave is made by passing paper strips (the weft) over one and under one of the strips or slits of a base paper (the warp), that each new row starts the opposite way so a chequered pattern forms, and that two colours make the pattern show. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.1.1), never as a phone question: b) create a plain paper weave to make.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.PERFOR.ROUNDS.ROUND', 'CREA.G3.PERFOR.ROUNDS', 'creative_activities', 3, 'Tell a round from other songs and say its message', ARRAY['CREA.G3.PERFOR.ROUNDS.a', 'CREA.G3.PERFOR.ROUNDS.c']::text[], 'The child says that in a round every group sings the same song but starts at a different time, in two or three parts, and each group keeps to its own part; tells a round from a song sung all together (unison); says the message of a round they sing; and names the performance techniques (good posture, the right tune, clear words, starting on time). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.2.1), never as a phone question: b) sing own part in a round applying appropriate performance techniques.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.PERFOR.GALLOPING.GALLOP', 'CREA.G3.PERFOR.GALLOPING', 'creative_activities', 3, 'Describe galloping and its directions and patterns', ARRAY['CREA.G3.PERFOR.GALLOPING.a']::text[], 'The child says galloping is a step with the leading foot and a quick close of the back foot behind it, the same foot always leading, like a horse; names the directions (forward, to the left, to the right) and floor patterns (straight, curved, circular, zigzag), and tells a gallop from a hop and a skip. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.2.1), never as a phone question: b) perform galloping movement in different directions for skill acquisition.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE', 'CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE', 'creative_activities', 3, 'Say what toy assemblage is and how the parts are joined', ARRAY['CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.a']::text[], 'The child says a toy made by assemblage is put together from found and recycled objects (boxes, bottle tops, sticks, wire, bottles) joined with glue, string, wire or rubber bands, names a toy made this way (a wire car, a bottle-top lorry, a box robot), and says sharp edges are covered and cans are washed first. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.2.1), never as a phone question: b) make toys using assemblage.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE', 'CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN', 'creative_activities', 3, 'Name the body parts used in a forward roll and a V-balance', ARRAY['CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.a']::text[], 'The child says that in a forward roll the hands go flat on the mat, the chin is tucked to the chest and the body rolls on the back of the shoulders with a round back (never on the top of the head), and that in a V-balance the child sits on the bottom with legs and upper body lifted to make a V and the arms out; names the markers that show where to start. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.2.1), never as a phone question: b) make markers for use during forward roll and V-balance performance in gymnastics; c) perform forward roll for skill acquisition; d) perform V-balance for skill acquisition.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN', 'creative_activities', 3, 'Identify indigenous string instruments and how they are played', ARRAY['CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.a']::text[], 'The child names indigenous string instruments from Kenyan communities (the orutu and wandindi fiddles, the ground bow, the mouth bow), says the sound comes from a string that vibrates, and names the three ways of playing: bowing (a fiddle), striking (a ground bow) and plucking (a mouth bow). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.2.1), never as a phone question: b) improvise a string musical instrument using available materials; c) play an improvised string instrument for enjoyment.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M', 'creative_activities', 3, 'Say how beads are made by the pellet technique', ARRAY['CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.a']::text[], 'The child orders bead making by the pellet technique: take a small lump of clay or paper pulp, roll it into a ball (a pellet) between the palms, pierce a hole through it with a stick while it is soft, dry it, paint it, and thread the beads into an ornament (a necklace or a bracelet). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.2.1), never as a phone question: b) model beads using the pellet technique; c) decorate the beads by painting; d) make an ornament using beads.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE', 'creative_activities', 3, 'Know the first stanza of the Kenya National Anthem in Kiswahili and its message', ARRAY['CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.a', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.b']::text[], 'The child puts the lines of the first stanza in order (Ee Mungu nguvu yetu, Ilete baraka kwetu, Haki iwe ngao na mlinzi, Natukae na undugu, Amani na uhuru, Raha tupate na ustawi) and says the stanza is a prayer to God asking for blessings, justice, living together as brothers and sisters, peace, freedom and plenty. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE', 'creative_activities', 3, 'Name occasions when the flag is raised and the anthem etiquette', ARRAY['CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.c']::text[], 'The child names occasions when the Kenya National Flag is raised (national holidays such as Madaraka, Mashujaa and Jamhuri Day, school assemblies, visits of the head of state, national meetings) and the etiquette of the anthem (stand still and upright, face the flag, hands at the sides, no talking, hats off). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G3.RUBRIC.3.1), never as a phone question: d) sing the Kenya National Anthem observing the anthem’s etiquette.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS', 'creative_activities', 3, 'Identify water points in the locality and their dangers', ARRAY['CREA.G3.APPREC.WATER_SAFETY_AWARENESS.a', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.b']::text[], 'The child names water points and water bodies in the locality (a river, a dam, a pond, a lake, a well, a borehole, a water tank, a swimming pool) and the dangers each holds (drowning, slipping, falling into an open well, dirty water that causes disease, a river that rises quickly after rain). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS', 'creative_activities', 3, 'Say how to stay safe around water points and water bodies', ARRAY['CREA.G3.APPREC.WATER_SAFETY_AWARENESS.c']::text[], 'The child names ways to keep safe (never go near water without an adult, keep away from open wells and fast or flooded rivers, keep tanks and wells covered, never push others near water) and says that if someone falls in, a child shouts for an adult and throws something that floats instead of jumping in. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'CREA.G2.CREATI.TURNING.a', 'outcome', 'essential', 'Moving the body in named directions (Grade 2 turning) comes before moving objects towards and away from the body. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
