INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'MATH.G3.GEOMET.SHAPES.NAME_SHAPES', 'skill', 'essential', 'Naming the basic shapes (Grade 3 Maths) is how regular shapes are picked out in a picture. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.d', 'outcome', 'essential', 'Painting regular shapes with a brush (Grade 2) comes before drawing a picture from regular and irregular shapes. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
