INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS', 'CREA.G2.CREATI.HOPPING.a', 'outcome', 'essential', 'The four directions of hopping and their floor patterns (Grade 2) are the same for skipping. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
