INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.PERFOR.ROUNDS.ROUND', 'CREA.G2.PERFOR.SONGS.b', 'outcome', 'essential', 'Saying the message of a topical song (Grade 2) is how the message of a round is found. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
