INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.a', 'outcome', 'helpful', 'Naming percussion instruments (Grade 1) begins sorting instruments by how they make sound. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'CREA.G2.PERFOR.MODELLING_COILING_TECHNI.b', 'outcome', 'essential', 'Rolling and shaping clay by coiling (Grade 2) uses the same hands as rolling pellets. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.b', 'outcome', 'essential', 'Making a plaited bracelet (Grade 2) is the first ornament; beads are threaded into the next. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.b', 'outcome', 'essential', 'Events at which the anthem is sung (Grade 2 Environmental Activities) come before learning its words and message. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'CREA.G2.PERFOR.SONGS.b', 'outcome', 'essential', 'Saying the message of a song (Grade 2) is how the message of the anthem is found. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'ENVI.G2.SOCIAL.OUR_NATIONAL_FLAG.c', 'outcome', 'essential', 'The etiquette of raising and lowering the flag (Grade 2 Environmental Activities) is the etiquette of the anthem. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'skill', 'helpful', 'Knowing the words of the anthem comes before singing it properly on these occasions. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.a', 'outcome', 'essential', 'Water points at school (Grade 2) come before water points and water bodies in the wider locality. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'ENVI.G3.RESOUR.WATER.a', 'outcome', 'helpful', 'How water is made dirty (Grade 3 Environmental Activities) explains the disease danger of water points. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'skill', 'essential', 'Knowing the dangers of each water point comes before naming how to stay safe from them. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.c', 'outcome', 'essential', 'Water safety rules at school (Grade 2) grow into rules for rivers, dams and wells. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL.M_CAC3_PP_TOWARDS_PUSH', 'CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'Calls bringing a bucket up from a well a push.', '{"question":"A girl brings a bucket of water up from a well with a rope. Is she pushing or pulling?","wrong_answer":"pushing","correct_answer":"pulling"}'::jsonb, 'The child links pushing with any hard work using the arms.', 'Offer "pushing" next to the right answer and ask the question again in a new context.', 'Ask: is the bucket coming towards her or going away from her?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL.M_CAC3_PP_WHEELBARROW', 'CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'Says a wheelbarrow being moved along is pulled because it moves forward.', '{"question":"A boy moves a wheelbarrow in front of him. Is he pushing or pulling?","wrong_answer":"pulling","correct_answer":"pushing"}'::jsonb, 'The child thinks moving forward always means pulling.', 'Offer "pulling" next to the right answer and ask the question again in a new context.', 'Push a chair across the floor, then pull it, and say where the chair is each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL.M_CAC3_PP_TUG_PUSH', 'CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'Thinks tug of war is a pushing game.', '{"question":"In tug of war, what do the two teams do with the rope?","wrong_answer":"push it","correct_answer":"pull it towards their side"}'::jsonb, 'Both teams lean hard, so the child sees a pushing contest.', 'Offer "push it" next to the right answer and ask the question again in a new context.', 'Hold a rope with a partner and pull it gently towards yourself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL.M_CAC3_PP_JERK_SAFE', 'CREA.G3.CREATI.PUSHING_AND_PULLING.PUSH_PULL', 'Thinks a sudden jerk is the best way to win a pulling game.', '{"question":"In a pulling game, what is the safe way to pull?","wrong_answer":"jerk the rope suddenly","correct_answer":"pull steadily and let go only when the teacher says"}'::jsonb, 'The child sees jerking as stronger and does not think of the other team falling.', 'Offer "jerk the rope suddenly" next to the right answer and ask the question again in a new context.', 'Show how a sudden jerk makes a partner fall, using a soft toy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING.M_CAC3_CM_BLUE_YELLOW', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'Says blue and yellow make brown or purple.', '{"question":"What colour do blue and yellow make when mixed?","wrong_answer":"purple","correct_answer":"green"}'::jsonb, 'The child guesses from the colours they like or has mixed too many colours at once and got brown.', 'Offer "purple" next to the right answer and ask the question again in a new context.', 'Mix one drop of blue into yellow in front of the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING.M_CAC3_CM_RED_YELLOW_PINK', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'Says red and yellow make pink.', '{"question":"What colour do red and yellow make?","wrong_answer":"pink","correct_answer":"orange"}'::jsonb, 'Pink is the light red the child knows best, so it is the first colour named.', 'Offer "pink" next to the right answer and ask the question again in a new context.', 'Mix red and yellow, then mix red and white, and compare the two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING.M_CAC3_CM_MORE_COLOURS', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'Thinks mixing more colours always gives a brighter colour.', '{"question":"Ama mixes red, blue, yellow and green together. What colour will she get?","wrong_answer":"a bright rainbow colour","correct_answer":"a dull brown"}'::jsonb, 'More colours seems like more brightness to the child.', 'Offer "a bright rainbow colour" next to the right answer and ask the question again in a new context.', 'Let the children mix all the colours in one cup and look.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING.M_CAC3_CM_BLOW_HARD', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.COLOUR_MIXING', 'Thinks blowing works best with a thick lump of paint.', '{"question":"For the blowing technique, what kind of paint do you use?","wrong_answer":"a thick lump of paint","correct_answer":"a drop of thin, watery paint"}'::jsonb, 'Thick paint looks like more colour to the child.', 'Offer "a thick lump of paint" next to the right answer and ask the question again in a new context.', 'Try blowing a thick blob and a watery drop with a straw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE.M_CAC3_SP_LEAF_REGULAR', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'Calls a leaf a regular shape because it has a name.', '{"question":"Is a leaf a regular shape or an irregular shape?","wrong_answer":"regular","correct_answer":"irregular"}'::jsonb, 'Everything with a name seems regular to the child.', 'Offer "regular" next to the right answer and ask the question again in a new context.', 'Draw a leaf and a square: does the leaf have a fixed form like the square?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE.M_CAC3_SP_TILTED_SQUARE', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'Says a square standing on its corner is not a square.', '{"question":"A square is turned so it stands on one corner. Is it still a square?","wrong_answer":"no, it is a diamond","correct_answer":"yes, it is still a square"}'::jsonb, 'Squares in books are always drawn sitting flat.', 'Offer "no, it is a diamond" next to the right answer and ask the question again in a new context.', 'Turn a paper square slowly and count its equal sides each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE.M_CAC3_SP_RECT_SQUARE', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'Calls every four-sided shape a square.', '{"question":"A door has two long sides and two short sides. Which shape is it?","wrong_answer":"a square","correct_answer":"a rectangle"}'::jsonb, 'Square is the first four-sided shape learnt.', 'Offer "a square" next to the right answer and ask the question again in a new context.', 'Measure the sides of a door and of a square tile with string.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE.M_CAC3_SP_CLOUD_CIRCLE', 'CREA.G3.CREATI.DRAWING_AND_PAINTING.SHAPES_PICTURE', 'Draws clouds and stones only as circles because they are roundish.', '{"question":"Which shape is a cloud usually: a circle or an irregular shape?","wrong_answer":"a circle","correct_answer":"an irregular shape"}'::jsonb, 'The child uses the nearest shape name for anything round.', 'Offer "a circle" next to the right answer and ask the question again in a new context.', 'Go outside and trace the edge of a cloud or a stone with a finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION.M_CAC3_SD_TATE_LONG', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'Thinks ta-te is longer than taa because it has two syllables.', '{"question":"Which takes longer: ta-te or taa?","wrong_answer":"ta-te","correct_answer":"they take the same time, one beat"}'::jsonb, 'Two syllables sound like more to the child.', 'Offer "ta-te" next to the right answer and ask the question again in a new context.', 'Walk one step to taa and one step to ta-te while clapping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION.M_CAC3_SD_LOUD_LONG', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'Says a loud sound is a long sound.', '{"question":"A drum is hit very hard once and stops quickly. Is it a long sound?","wrong_answer":"yes, because it is loud","correct_answer":"no, it is loud but short"}'::jsonb, 'The child mixes loudness with length.', 'Offer "yes, because it is loud" next to the right answer and ask the question again in a new context.', 'Play one loud short sound and one soft long hum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION.M_CAC3_SD_TAAAA_TWO', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'Counts taa-aa-aa-aa as two beats.', '{"question":"How many beats is taa-aa-aa-aa?","wrong_answer":"two","correct_answer":"four"}'::jsonb, 'The child counts the sound as one word plus a long ending.', 'Offer "two" next to the right answer and ask the question again in a new context.', 'Tap your knee for each "aa" while holding the sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION.M_CAC3_SD_WORD_RHYTHM', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.SOUND_DURATION', 'Claps one clap per word instead of per syllable.', '{"question":"How many claps for \"Ke-nya\"?","wrong_answer":"one","correct_answer":"two"}'::jsonb, 'The child claps for whole words, as when counting words in English.', 'Offer "one" next to the right answer and ask the question again in a new context.', 'Say the word slowly and clap each part: Ke, nya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT.M_CAC3_RR_ROWS', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT', 'Thinks a random repeat pattern must be printed in straight rows.', '{"question":"In a random repeat pattern, where do you place the prints?","wrong_answer":"in straight rows only","correct_answer":"anywhere on the paper"}'::jsonb, 'All patterns seen before were in rows.', 'Offer "in straight rows only" next to the right answer and ask the question again in a new context.', 'Show a row pattern and a random repeat side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT.M_CAC3_RR_DIFFERENT', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT', 'Uses a different object for every print and calls it a repeat pattern.', '{"question":"Juma prints a leaf, then a bottle top, then a coin, all different. Is it a repeat pattern?","wrong_answer":"yes","correct_answer":"no; a repeat pattern uses the same print again and again"}'::jsonb, 'The child hears "random" and thinks anything goes.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Ask: which print repeats? If none, it is not a repeat pattern.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT.M_CAC3_RR_DRY_PRINT', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT', 'Presses a dry object on paper and expects a print.', '{"question":"What must you do to a leaf before you print with it?","wrong_answer":"nothing, just press it","correct_answer":"put paint on it"}'::jsonb, 'The child has seen the print but not the inking step.', 'Offer "nothing, just press it" next to the right answer and ask the question again in a new context.', 'Press a dry leaf, then a painted leaf, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT.M_CAC3_RR_FOUND', 'CREA.G3.CREATI.RHYTHM_AND_PATTERN_MAKIN.RANDOM_REPEAT', 'Thinks only bought stamps can be used for printing.', '{"question":"Which can you use to print a pattern?","wrong_answer":"only a stamp from a shop","correct_answer":"found objects such as a leaf, a bottle top or a cut potato"}'::jsonb, 'The child has seen printing only with shop stamps.', 'Offer "only a stamp from a shop" next to the right answer and ask the question again in a new context.', 'Collect objects from the school compound and test them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS.M_CAC3_SK_LEFT_RIGHT', 'CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS', 'Mixes up right and left, naming the teacher''s right as their own.', '{"question":"Face the board and skip to your right. Which hand points the way?","wrong_answer":"my left hand","correct_answer":"my right hand, the one I write with if I am right-handed"}'::jsonb, 'The child copies the teacher who faces them, so sides are mirrored.', 'Offer "my left hand" next to the right answer and ask the question again in a new context.', 'Stand with your back to the class and point right, then let children copy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS.M_CAC3_SK_ZIGZAG_CURVE', 'CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS', 'Calls a curved path a zigzag.', '{"question":"A path goes like a snake, smooth and bending. Is it a zigzag?","wrong_answer":"yes","correct_answer":"no, it is curved"}'::jsonb, 'Both paths change direction, so the child uses the word they like.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Chalk a zigzag with sharp corners and a curve with none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS.M_CAC3_SK_BACKWARD_TURN', 'CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS', 'Thinks skipping backward means turning round and skipping forward.', '{"question":"What does skipping backward mean?","wrong_answer":"turn round and skip forward","correct_answer":"keep facing the front and move backwards"}'::jsonb, 'The child turns round to see where they are going.', 'Offer "turn round and skip forward" next to the right answer and ask the question again in a new context.', 'Put a mark in front and keep your eyes on it while moving back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS.M_CAC3_SK_CIRCLE_SPIN', 'CREA.G3.CREATI.SKIPPING.SKIP_DIRECTIONS', 'Thinks a circular pattern means spinning on the spot.', '{"question":"Skip in a circular pattern. What do you do?","wrong_answer":"spin round on the spot","correct_answer":"skip along the line of a big circle on the ground"}'::jsonb, 'Circle and spinning both go round.', 'Offer "spin round on the spot" next to the right answer and ask the question again in a new context.', 'Draw a big circle and skip along its edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.COLLAGE.COLLAGE.M_CAC3_CO_DRAWING', 'CREA.G3.CREATI.COLLAGE.COLLAGE', 'Thinks a collage is a coloured drawing.', '{"question":"Which picture is a collage?","wrong_answer":"a picture coloured with crayons","correct_answer":"a picture made by pasting pieces of paper, cloth and seeds"}'::jsonb, 'All pictures look alike to the child at first.', 'Offer "a picture coloured with crayons" next to the right answer and ask the question again in a new context.', 'Touch a collage: feel the pieces stuck on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.COLLAGE.COLLAGE.M_CAC3_CO_ONE_MATERIAL', 'CREA.G3.CREATI.COLLAGE.COLLAGE', 'Thinks a collage must use only one material, like a mosaic.', '{"question":"Can a collage use paper, cloth and seeds together?","wrong_answer":"no, only one material","correct_answer":"yes, many different materials"}'::jsonb, 'The Grade 2 mosaic used small pieces of one kind.', 'Offer "no, only one material" next to the right answer and ask the question again in a new context.', 'Show a collage with paper, cloth and feathers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.COLLAGE.COLLAGE.M_CAC3_CO_WET_LEAVES', 'CREA.G3.CREATI.COLLAGE.COLLAGE', 'Pastes leaves straight from the ground, wet and dirty.', '{"question":"What do you do to leaves before you paste them in a collage?","wrong_answer":"paste them straight away","correct_answer":"clean and dry them first"}'::jsonb, 'The child does not know wet leaves rot and do not stick.', 'Offer "paste them straight away" next to the right answer and ask the question again in a new context.', 'Paste one wet leaf and one dry leaf and check the next day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.COLLAGE.COLLAGE.M_CAC3_CO_GLUE_ONLY', 'CREA.G3.CREATI.COLLAGE.COLLAGE', 'Thinks a collage cannot be made without shop glue.', '{"question":"You have no glue. What can you use to paste a collage?","wrong_answer":"nothing, you cannot make it","correct_answer":"a paste of flour or cassava and water"}'::jsonb, 'The child has only seen glue from a shop.', 'Offer "nothing, you cannot make it" next to the right answer and ask the question again in a new context.', 'Mix flour and water together and test it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.MELODY_VARIATION.M_CAC3_MV_LOUD_HIGH', 'CREA.G3.CREATI.MELODY.MELODY_VARIATION', 'Calls a louder version of a tune higher.', '{"question":"The class sings a song again, louder but on the same notes. What changed?","wrong_answer":"it got higher","correct_answer":"it got louder"}'::jsonb, 'In daily speech "turn it up" means both louder and higher.', 'Offer "it got higher" next to the right answer and ask the question again in a new context.', 'Sing the same note softly then loudly; then a low note and a high note.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.MELODY_VARIATION.M_CAC3_MV_FAST_HIGH', 'CREA.G3.CREATI.MELODY.MELODY_VARIATION', 'Says a faster tune is a higher tune.', '{"question":"A song is sung again more quickly. What changed?","wrong_answer":"the pitch went higher","correct_answer":"the tempo got faster"}'::jsonb, 'Fast songs often feel excited and high to the child.', 'Offer "the pitch went higher" next to the right answer and ask the question again in a new context.', 'Sing a low tune quickly and a high tune slowly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.MELODY_VARIATION.M_CAC3_MV_NEW_SONG', 'CREA.G3.CREATI.MELODY.MELODY_VARIATION', 'Thinks a tune with new words is a new song.', '{"question":"The tune stays the same but the words change. Is it a new tune?","wrong_answer":"yes, a new tune","correct_answer":"no, the same tune with new words"}'::jsonb, 'The child remembers songs by their words.', 'Offer "yes, a new tune" next to the right answer and ask the question again in a new context.', 'Hum the tune without words, then sing both versions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.MELODY_VARIATION.M_CAC3_MV_NO_CHANGE', 'CREA.G3.CREATI.MELODY.MELODY_VARIATION', 'Says nothing changed when only the speed changed.', '{"question":"The song was sung slowly, then fast. Did anything change?","wrong_answer":"no, it is the same song","correct_answer":"yes, the tempo changed"}'::jsonb, 'The child listens only for the words and tune.', 'Offer "no, it is the same song" next to the right answer and ask the question again in a new context.', 'March to the song slowly and then fast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.PERF_DIRECTIONS.M_CAC3_PD_LOUD_SHOUT', 'CREA.G3.CREATI.MELODY.PERF_DIRECTIONS', 'Thinks singing loud means shouting.', '{"question":"The teacher says \"loud\". How do you sing?","wrong_answer":"shout as hard as you can","correct_answer":"sing strongly but still in tune"}'::jsonb, 'Loud is the same as shouting in the playground.', 'Offer "shout as hard as you can" next to the right answer and ask the question again in a new context.', 'Sing loud, then shout, and listen for which keeps the tune.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.PERF_DIRECTIONS.M_CAC3_PD_SOFT_SLOW', 'CREA.G3.CREATI.MELODY.PERF_DIRECTIONS', 'Slows down when told to sing softly.', '{"question":"The teacher says \"soft\". What changes?","wrong_answer":"we sing slower","correct_answer":"we sing more quietly at the same speed"}'::jsonb, 'Soft and slow often go together in lullabies.', 'Offer "we sing slower" next to the right answer and ask the question again in a new context.', 'Clap a steady beat and sing softly over it without slowing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.PERF_DIRECTIONS.M_CAC3_PD_FAST_LOUD', 'CREA.G3.CREATI.MELODY.PERF_DIRECTIONS', 'Gets louder when told to sing fast.', '{"question":"The teacher says \"fast\". What changes?","wrong_answer":"we sing louder","correct_answer":"we sing more quickly"}'::jsonb, 'Excitement makes the child sing faster and louder together.', 'Offer "we sing louder" next to the right answer and ask the question again in a new context.', 'Sing fast and soft, like a whisper race.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.MELODY.PERF_DIRECTIONS.M_CAC3_PD_HAND_SIGN', 'CREA.G3.CREATI.MELODY.PERF_DIRECTIONS', 'Reads hands held close together as loud.', '{"question":"The teacher holds her hands close together. What does it mean?","wrong_answer":"sing loud","correct_answer":"sing soft"}'::jsonb, 'The child has not linked the size of the gap to the size of the sound.', 'Offer "sing loud" next to the right answer and ask the question again in a new context.', 'Open the hands wide and sing big; close them and sing small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.WEAVING.PAPER_WEAVE.M_CAC3_WV_SAME_START', 'CREA.G3.CREATI.WEAVING.PAPER_WEAVE', 'Starts every row the same way (over first), so the strips slide out.', '{"question":"Row 1 started over. How should row 2 start?","wrong_answer":"over, the same as row 1","correct_answer":"under, the opposite of row 1"}'::jsonb, 'The child copies the row above exactly.', 'Offer "over, the same as row 1" next to the right answer and ask the question again in a new context.', 'Weave two rows the same way and lift the paper: the strip falls out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.WEAVING.PAPER_WEAVE.M_CAC3_WV_OVER_TWO', 'CREA.G3.CREATI.WEAVING.PAPER_WEAVE', 'Goes over two strips and under one in a plain weave.', '{"question":"In a plain weave, how does the strip go?","wrong_answer":"over two, under one","correct_answer":"over one, under one"}'::jsonb, 'The child skips strips by accident when the slits are close.', 'Offer "over two, under one" next to the right answer and ask the question again in a new context.', 'Say "over, under, over, under" aloud with each strip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.WEAVING.PAPER_WEAVE.M_CAC3_WV_CUT_EDGE', 'CREA.G3.CREATI.WEAVING.PAPER_WEAVE', 'Cuts the slits right through to the edge of the base paper.', '{"question":"When you cut slits in the base paper, how far do you cut?","wrong_answer":"right to the edge","correct_answer":"stop before the edge so the paper holds together"}'::jsonb, 'The child cuts until the scissors stop.', 'Offer "right to the edge" next to the right answer and ask the question again in a new context.', 'Show a base cut to the edge falling into strips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.CREATI.WEAVING.PAPER_WEAVE.M_CAC3_WV_ONE_COLOUR', 'CREA.G3.CREATI.WEAVING.PAPER_WEAVE', 'Thinks the colours of the strips do not matter to the pattern.', '{"question":"Why use two colours in a paper weave?","wrong_answer":"it does not matter","correct_answer":"so the over and under pattern shows"}'::jsonb, 'The child has not seen a weave in one colour.', 'Offer "it does not matter" next to the right answer and ask the question again in a new context.', 'Compare a weave in one colour with one in two colours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.ROUNDS.ROUND.M_CAC3_RO_DIFFERENT_SONGS', 'CREA.G3.PERFOR.ROUNDS.ROUND', 'Thinks the groups in a round sing different songs.', '{"question":"In a round, what do the groups sing?","wrong_answer":"different songs","correct_answer":"the same song, starting at different times"}'::jsonb, 'The sound is mixed, so the child thinks the songs differ.', 'Offer "different songs" next to the right answer and ask the question again in a new context.', 'Sing the round slowly with two groups, then each group alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.ROUNDS.ROUND.M_CAC3_RO_TOGETHER', 'CREA.G3.PERFOR.ROUNDS.ROUND', 'Thinks a round starts with all groups together.', '{"question":"Do all groups start a round together?","wrong_answer":"yes","correct_answer":"no, one group starts, then the next joins later"}'::jsonb, 'Most class songs start together.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Point to group 1 to start; point to group 2 after one line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.ROUNDS.ROUND.M_CAC3_RO_JOIN_OTHER', 'CREA.G3.PERFOR.ROUNDS.ROUND', 'Switches to the other group''s words when they hear them.', '{"question":"In a round you hear the other group singing a different line. What do you do?","wrong_answer":"join their line","correct_answer":"keep singing your own part"}'::jsonb, 'The child follows the loudest voices.', 'Offer "join their line" next to the right answer and ask the question again in a new context.', 'Practise with a hand over one ear, keeping your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.ROUNDS.ROUND.M_CAC3_RO_UNISON', 'CREA.G3.PERFOR.ROUNDS.ROUND', 'Calls a song sung all together a round.', '{"question":"The whole class sings the same words at the same time. Is that a round?","wrong_answer":"yes","correct_answer":"no, it is singing in unison"}'::jsonb, 'Any group song seems a round to the child.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Sing a song in unison, then as a round, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.GALLOPING.GALLOP.M_CAC3_GA_HOP', 'CREA.G3.PERFOR.GALLOPING.GALLOP', 'Thinks galloping is hopping on one leg.', '{"question":"Is galloping the same as hopping?","wrong_answer":"yes","correct_answer":"no; in galloping both feet touch the ground, one leading"}'::jsonb, 'Both are bouncy moves.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Hop on one foot, then gallop, and watch the feet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.GALLOPING.GALLOP.M_CAC3_GA_SWAP', 'CREA.G3.PERFOR.GALLOPING.GALLOP', 'Swaps the leading foot every step.', '{"question":"In a gallop, which foot leads?","wrong_answer":"the feet take turns","correct_answer":"the same foot leads every time"}'::jsonb, 'Walking and running swap feet, so the child does the same.', 'Offer "the feet take turns" next to the right answer and ask the question again in a new context.', 'Put a ribbon on the leading foot and keep it in front.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.GALLOPING.GALLOP.M_CAC3_GA_SKIP', 'CREA.G3.PERFOR.GALLOPING.GALLOP', 'Calls a skip a gallop.', '{"question":"Step-hop, step-hop, changing feet. Is that a gallop?","wrong_answer":"yes","correct_answer":"no, that is skipping"}'::jsonb, 'Both moves have a quick rhythm.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Do a gallop and a skip to the same drum and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.GALLOPING.GALLOP.M_CAC3_GA_SIDE', 'CREA.G3.PERFOR.GALLOPING.GALLOP', 'Thinks you cannot gallop to the side.', '{"question":"Can you gallop to the left?","wrong_answer":"no, only forward","correct_answer":"yes, leading with the left foot"}'::jsonb, 'Horses are seen galloping forward.', 'Offer "no, only forward" next to the right answer and ask the question again in a new context.', 'Face the board and gallop to the left, left foot leading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE.M_CAC3_TA_BOUGHT', 'CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE', 'Thinks toys can only be bought from a shop.', '{"question":"Can you make a toy car from bottle tops and a box?","wrong_answer":"no, toys come from shops","correct_answer":"yes, by joining found objects"}'::jsonb, 'The child has seen toys only in shops.', 'Offer "no, toys come from shops" next to the right answer and ask the question again in a new context.', 'Show a wire car made in the community.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE.M_CAC3_TA_DRAWN', 'CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE', 'Thinks assemblage is drawing a toy on paper.', '{"question":"What is a toy made by assemblage?","wrong_answer":"a drawing of a toy","correct_answer":"a toy built by joining real objects together"}'::jsonb, 'The word is new, and most art lessons are on paper.', 'Offer "a drawing of a toy" next to the right answer and ask the question again in a new context.', 'Hold an assemblage toy and turn it round.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE.M_CAC3_TA_SHARP', 'CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE', 'Uses opened tins with sharp edges as they are.', '{"question":"What do you do with the sharp edge of a tin before using it?","wrong_answer":"nothing","correct_answer":"ask an adult to cover or fold it"}'::jsonb, 'The child does not see the danger.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Show how tape covers a tin edge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE.M_CAC3_TA_ONE_JOIN', 'CREA.G3.PERFOR.SCULPTURE_TOY_ASSEMBLAGE.ASSEMBLAGE', 'Thinks parts can only be joined with glue.', '{"question":"You have no glue. How else can you join the wheels to a box car?","wrong_answer":"you cannot","correct_answer":"with string, wire, sticks or rubber bands"}'::jsonb, 'Glue is the only joining material the child knows.', 'Offer "you cannot" next to the right answer and ask the question again in a new context.', 'Join two boxes with string, then with a rubber band.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE.M_CAC3_FR_HEAD_TOP', 'CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE', 'Thinks a forward roll goes over the top of the head.', '{"question":"In a forward roll, which part touches the mat first after the hands?","wrong_answer":"the top of the head","correct_answer":"the back of the shoulders, with the chin tucked in"}'::jsonb, 'From the side a roll looks like going over the head.', 'Offer "the top of the head" next to the right answer and ask the question again in a new context.', 'Tuck the chin onto a bean bag held at the chest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE.M_CAC3_FR_STRAIGHT_BACK', 'CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE', 'Keeps a straight back in a forward roll.', '{"question":"What shape is your back in a forward roll?","wrong_answer":"straight and flat","correct_answer":"round, like a ball"}'::jsonb, 'The child is used to standing up straight.', 'Offer "straight and flat" next to the right answer and ask the question again in a new context.', 'Rock on the back like a rocking chair first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE.M_CAC3_VB_FEET_DOWN', 'CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE', 'Keeps the feet on the floor in a V-balance.', '{"question":"In a V-balance, where are your feet?","wrong_answer":"on the floor","correct_answer":"lifted up off the floor"}'::jsonb, 'The child sits up but is afraid to lift the legs.', 'Offer "on the floor" next to the right answer and ask the question again in a new context.', 'Lift one leg, then both, holding the knees first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE.M_CAC3_VB_LYING', 'CREA.G3.PERFOR.FORWARD_ROLL_AND_V_BALAN.ROLL_BALANCE', 'Thinks the V-balance is done lying flat on the back.', '{"question":"What part of the body do you balance on in a V-balance?","wrong_answer":"the whole back, lying flat","correct_answer":"the bottom"}'::jsonb, 'The child lies back when the legs go up.', 'Offer "the whole back, lying flat" next to the right answer and ask the question again in a new context.', 'Sit and lift legs and chest together, arms out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR.M_CAC3_SI_ORUTU_DRUM', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'Calls the orutu a drum because it has a skin.', '{"question":"The orutu has a string and a bow. What kind of instrument is it?","wrong_answer":"a drum","correct_answer":"a string instrument (a fiddle)"}'::jsonb, 'The orutu has a skin-covered resonator like a drum.', 'Offer "a drum" next to the right answer and ask the question again in a new context.', 'Bow the string and listen: the string makes the sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR.M_CAC3_SI_BOW_PLUCK', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'Thinks a fiddle is played by plucking with the fingers.', '{"question":"How is a fiddle such as the wandindi played?","wrong_answer":"by plucking","correct_answer":"by bowing: rubbing a bow across the string"}'::jsonb, 'Guitars, which are plucked, are the string instrument the child knows.', 'Offer "by plucking" next to the right answer and ask the question again in a new context.', 'Rub a bow across a string and then pluck it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR.M_CAC3_SI_WIND', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'Thinks the mouth bow is a wind instrument because it is held to the mouth.', '{"question":"A mouth bow is held near the mouth and its string is plucked. Is it a wind instrument?","wrong_answer":"yes, because it uses the mouth","correct_answer":"no, it is a string instrument"}'::jsonb, 'The mouth makes the child think of blowing.', 'Offer "yes, because it uses the mouth" next to the right answer and ask the question again in a new context.', 'Pluck the string with the mouth closed, then open, and hear the change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR.M_CAC3_SI_STRING_TIGHT', 'CREA.G3.PERFOR.STRING_MUSICAL_INSTRUMEN.STRING_INSTR', 'Thinks a loose string makes the clearest sound.', '{"question":"Which string makes a clear sound: a loose one or a tight one?","wrong_answer":"a loose one","correct_answer":"a tight one"}'::jsonb, 'A loose string moves a lot, so the child expects a big sound.', 'Offer "a loose one" next to the right answer and ask the question again in a new context.', 'Pluck a rubber band loose, then stretched.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS.M_CAC3_BD_HOLE_DRY', 'CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'Makes the hole after the bead has dried.', '{"question":"When do you make the hole in a clay bead?","wrong_answer":"after it dries","correct_answer":"while it is still soft"}'::jsonb, 'Painting comes after drying, so the child puts every step after drying.', 'Offer "after it dries" next to the right answer and ask the question again in a new context.', 'Try to push a stick through a dry bead and a soft bead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS.M_CAC3_BD_PELLET_COIL', 'CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'Rolls a long coil instead of a ball when told to make a pellet.', '{"question":"In the pellet technique, what shape do you roll?","wrong_answer":"a long coil","correct_answer":"a small ball"}'::jsonb, 'Coiling was learnt in Grade 2.', 'Offer "a long coil" next to the right answer and ask the question again in a new context.', 'Roll between flat palms in circles, not back and forth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS.M_CAC3_BD_PAINT_WET', 'CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'Paints beads while the clay is still wet.', '{"question":"When do you paint clay beads?","wrong_answer":"straight away, while wet","correct_answer":"after they are dry"}'::jsonb, 'The child wants to finish quickly.', 'Offer "straight away, while wet" next to the right answer and ask the question again in a new context.', 'Paint one wet bead and one dry bead and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS.M_CAC3_BD_SUN_DRY', 'CREA.G3.PERFOR.MODELLING_AND_ORNAMENT_M.BEADS', 'Dries beads in hot sun to make them dry quickly.', '{"question":"Where do you dry clay beads?","wrong_answer":"in hot sun","correct_answer":"in the shade"}'::jsonb, 'The child knows the sun dries washing fast.', 'Offer "in hot sun" next to the right answer and ask the question again in a new context.', 'Dry two beads, one in hot sun and one in shade; look for cracks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT.M_CAC3_NA_FIRST_LINE', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'Starts the first stanza with "Amani na uhuru".', '{"question":"Which line starts the first stanza of the Kenya National Anthem?","wrong_answer":"Amani na uhuru","correct_answer":"Ee Mungu nguvu yetu"}'::jsonb, 'The child remembers the words they like best.', 'Offer "Amani na uhuru" next to the right answer and ask the question again in a new context.', 'Sing the stanza line by line and number the lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT.M_CAC3_NA_MESSAGE_WAR', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'Says the anthem is about fighting a war.', '{"question":"What is the first stanza of the anthem about?","wrong_answer":"fighting a war","correct_answer":"a prayer to God for blessings, justice, unity, peace and freedom"}'::jsonb, 'National songs are linked in the child''s mind with soldiers.', 'Offer "fighting a war" next to the right answer and ask the question again in a new context.', 'Read the meaning of each line: baraka is blessing, amani is peace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT.M_CAC3_NA_UNDUGU', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'Thinks "undugu" means only one''s own family.', '{"question":"In the anthem, \"Natukae na undugu\" asks us to...","wrong_answer":"live only with our own family","correct_answer":"live together as brothers and sisters, all Kenyans"}'::jsonb, 'Ndugu at home means a brother or sister.', 'Offer "live only with our own family" next to the right answer and ask the question again in a new context.', 'Ask: in the anthem, who are our brothers and sisters?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT.M_CAC3_NA_BARAKA', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_TEXT', 'Thinks "baraka" means strength.', '{"question":"What does \"baraka\" mean in \"Ilete baraka kwetu\"?","wrong_answer":"strength","correct_answer":"blessings"}'::jsonb, '"Nguvu" (strength) comes in the line just before.', 'Offer "strength" next to the right answer and ask the question again in a new context.', 'Say each line and its meaning slowly, one at a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS.M_CAC3_NA_SIT', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'Thinks it is fine to sit or walk while the anthem is sung.', '{"question":"What do you do while the national anthem is sung?","wrong_answer":"keep walking to class","correct_answer":"stand still and upright, facing the flag"}'::jsonb, 'The child does not yet see the anthem as a special moment.', 'Offer "keep walking to class" next to the right answer and ask the question again in a new context.', 'Practise stopping and standing still as soon as the anthem begins.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS.M_CAC3_NA_ONLY_SCHOOL', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'Thinks the flag is raised only at school.', '{"question":"Name an occasion other than school assembly when the flag is raised.","wrong_answer":"there is none","correct_answer":"a national holiday such as Jamhuri Day"}'::jsonb, 'The child has only seen the flag raised at school.', 'Offer "there is none" next to the right answer and ask the question again in a new context.', 'Look at pictures of Jamhuri Day celebrations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS.M_CAC3_NA_HAT_ON', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'Keeps a cap on during the anthem.', '{"question":"A boy is wearing a cap when the anthem starts. What should he do?","wrong_answer":"keep it on","correct_answer":"take it off"}'::jsonb, 'The child does not know the etiquette.', 'Offer "keep it on" next to the right answer and ask the question again in a new context.', 'Show the class how to remove a cap and hold it at the side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS.M_CAC3_NA_MADARAKA_BIRTHDAY', 'CREA.G3.APPREC.THE_KENYA_NATIONAL_ANTHE.ANTHEM_OCCASIONS', 'Names a birthday party as a national occasion for raising the flag.', '{"question":"Which is a day when the national flag is raised?","wrong_answer":"a birthday party","correct_answer":"Madaraka Day"}'::jsonb, 'Every celebration seems the same to the child.', 'Offer "a birthday party" next to the right answer and ask the question again in a new context.', 'Sort celebration cards into family and national.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS.M_CAC3_WD_SHALLOW_SAFE', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'Thinks shallow water cannot be dangerous.', '{"question":"Can a small child drown in shallow water?","wrong_answer":"no, it is too shallow","correct_answer":"yes, even shallow water can drown a child"}'::jsonb, 'Drowning is linked only with deep lakes and the sea.', 'Offer "no, it is too shallow" next to the right answer and ask the question again in a new context.', 'Talk about a basin, a puddle and a pond: a face in water is dangerous anywhere.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS.M_CAC3_WD_TANK_NOT', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'Thinks a water tank or well at home is not a water point.', '{"question":"Is a water tank at home a water point?","wrong_answer":"no, only rivers are","correct_answer":"yes"}'::jsonb, 'The child thinks of water points as wild places.', 'Offer "no, only rivers are" next to the right answer and ask the question again in a new context.', 'List all the places water is kept at home and in school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS.M_CAC3_WD_CLEAR_CLEAN', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'Thinks clear river water is always clean to drink.', '{"question":"River water looks clear. Is it safe to drink without boiling?","wrong_answer":"yes, it looks clean","correct_answer":"no, it can carry germs you cannot see"}'::jsonb, 'The child judges water by how it looks.', 'Offer "yes, it looks clean" next to the right answer and ask the question again in a new context.', 'Look at a drop of pond water under a hand lens, or show a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS.M_CAC3_WD_RAIN_RIVER', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_DANGERS', 'Thinks a river is safe to cross after rain because the rain has stopped.', '{"question":"It rained heavily upstream. Is the river safe to cross now?","wrong_answer":"yes, the rain has stopped","correct_answer":"no, the river can rise and flow fast"}'::jsonb, 'The child does not link rain far away with the river nearby.', 'Offer "yes, the rain has stopped" next to the right answer and ask the question again in a new context.', 'Show how water poured at one end of a gutter reaches the other end later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY.M_CAC3_WS_JUMP_IN', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'Says you should jump in to save a friend who has fallen into water.', '{"question":"Your friend falls into a dam. What should you do?","wrong_answer":"jump in and pull them out","correct_answer":"shout for an adult and throw something that floats"}'::jsonb, 'The child wants to help and thinks being brave means jumping in.', 'Offer "jump in and pull them out" next to the right answer and ask the question again in a new context.', 'Role play: shout, find an adult, throw a jerrican or a stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY.M_CAC3_WS_ALONE_SWIM', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'Thinks a child who can swim may swim alone in a river.', '{"question":"Can a child who can swim go into a river alone?","wrong_answer":"yes, if they can swim","correct_answer":"no, never without an adult"}'::jsonb, 'Being able to swim feels like being safe.', 'Offer "yes, if they can swim" next to the right answer and ask the question again in a new context.', 'Talk about strong currents and hidden rocks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY.M_CAC3_WS_PUSH_GAME', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'Thinks pushing friends near water is just a game.', '{"question":"Is it all right to push a friend near a well as a joke?","wrong_answer":"yes, it is a game","correct_answer":"no, they could fall in"}'::jsonb, 'The child does not think of the result of a joke.', 'Offer "yes, it is a game" next to the right answer and ask the question again in a new context.', 'Ask: what could happen next?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY.M_CAC3_WS_OPEN_WELL', 'CREA.G3.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFETY', 'Leaves the cover off a well after drawing water.', '{"question":"You finish drawing water from a well. What do you do?","wrong_answer":"leave it open for the next person","correct_answer":"cover it again"}'::jsonb, 'The child wants to be helpful to the next person.', 'Offer "leave it open for the next person" next to the right answer and ask the question again in a new context.', 'Ask: who else might walk past an open well?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
